1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Canonical form of a postal address, applied whenever an owner is created: trim and collapse
7	 * whitespace, upper-case, and expand common abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE).
8	 * Blank input (or input that is blank once trimmed) normalizes to {@code ""}. Used both to store the
9	 * address and for every address comparison (household duplicate detection and the shared household id).
10	 */
11	public final class AddressNormalizer {
12	
13	    private static final Map<String, String> ABBREVIATIONS =
14	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
15	
16	    private AddressNormalizer() {
17	    }
18	
19	    public static String normalize(String raw) {
20	        String collapsed = (raw == null ? "" : raw).trim().replaceAll("\\s+", " ").toUpperCase();
21	        if (collapsed.isEmpty()) {
22	            return "";
23	        }
24	        StringBuilder sb = new StringBuilder(collapsed.length());
25	        for (String token : collapsed.split(" ")) {
26	            if (sb.length() > 0) {
27	                sb.append(' ');
28	            }
29	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
30	        }
31	        return sb.toString();
32	    }
33	}
